class WriteThroughCache:
    def __init__(self, cache, db):
        self.cache = cache
        self.db = db

    def write(self, key, value):
        # Synchronous dual write: both must succeed.
        try:
            self.db.write(key, value)      # authoritative store first
        except DbError:
            self.cache.delete(key)         # never leave a phantom value
            raise
        self.cache.set(key, value)         # publish only after DB confirms
        return True

    def read(self, key):
        value = self.cache.get(key)
        if value is not None:
            return value                   # hit is safe: cache never leads DB
        value = self.db.read(key)          # miss: load and fill
        if value is not None:
            self.cache.set(key, value)
        return value
